/**
 * File Name: i18n.ts
 * Purpose: Localization read helpers — localized-field detection, ?locale=
 *          validation, side-table row fetches, and the response-shaping
 *          overlay that merges translations over main-table values with
 *          per-field fallback to the default locale.
 *
 * Author: Raghunath J
 * License: MIT
 *
 * Dependencies/Notes: Side tables (<type>_i18n) are generated by tangen push
 *          and exposed via @tangen/db/content-tables `contentI18nTables`.
 *          Default-locale values always live in the main table — a null/absent
 *          side value falls back automatically.
 */
import { eq, and, inArray } from 'drizzle-orm'
// Namespace import + fallback: generated files (and test mocks) that predate
// localization export no contentI18nTables — treat that as "no side tables".
import * as generated from '@tangen/db/content-tables'
import type { LocalizationConfig } from '@tangen/types'
import { isLocalizableFieldType } from '@tangen/types'
import { RequestError } from '../lib/errors'
import { localizedContainerFields } from '@tangen/schema'

const contentI18nTables: Record<string, any> = (generated as any).contentI18nTables ?? {}

/**
 * Names of the fields on a type marked `localized: true`. Media fields are
 * excluded — they localize at the asset level (metadata.localeAssets variants),
 * so the stored reference is shared across locales.
 */
export function localizedFieldNames(typeDef: { fields: { name: string; fieldType?: string; config?: Record<string, unknown> }[] }): string[] {
  return (typeDef.fields ?? [])
    .filter((f) => (f.config as any)?.localized === true && isLocalizableFieldType(f.fieldType ?? ''))
    .map((f) => f.name)
}

/**
 * Validates the ?locale= request param against the workspace localization
 * config. Returns null for "serve the main table" (no param, or the default
 * locale), 'all' for the member-only full-map read, or a concrete non-default
 * locale code.
 */
export function resolveLocaleParam(
  locale: string | undefined | null,
  localization: LocalizationConfig | undefined | null,
  isMember: boolean,
): string | null {
  if (!locale) return null
  if (!localization || localization.enabled !== true) {
    // The admin editor always asks for the full map (?locale=all) - on a
    // workspace without localization that means "the main row", not an error;
    // otherwise every editor in a fresh project opens empty on a 422.
    if (locale === 'all') return null
    throw new RequestError('VALIDATION_ERROR', 'Localization is not enabled for this workspace', 422)
  }
  if (locale === 'all') {
    if (!isMember) throw new RequestError('VALIDATION_ERROR', "locale=all is admin-panel only", 422)
    return 'all'
  }
  if (locale === localization.defaultLocale) return null
  const known = (localization.locales ?? []).some((l) => l?.code === locale)
  if (!known) {
    throw new RequestError('VALIDATION_ERROR', `Unknown locale "${locale}"`, 422)
  }
  return locale
}

/** How a read request wants translations served. */
export type ReadLocales =
  | { mode: 'overlay'; locale: string }
  | { mode: 'map'; locales: string[] | 'all' }
  | null

/**
 * Resolves a read ?locale= into overlay vs map mode:
 * - a single non-default code → overlay (per-field fallback, today's shape)
 * - 'all' → attach the full per-row `i18n` translations map
 * - a comma-separated list ('de,ta') → attach the map for those locales
 * The default locale alone (or no param) means the main row as-is.
 */
export function resolveReadLocales(
  locale: string | undefined | null,
  localization: LocalizationConfig | undefined | null,
  opts: { isMember?: boolean } = {},
): ReadLocales {
  if (!locale) return null
  if (!localization || localization.enabled !== true) {
    // The admin's merged read on a workspace without localization. K0: that
    // pass belongs to members; a key asking for `all` here is refused like
    // any other locale param on a workspace that has none.
    if (locale === 'all' && opts.isMember === true) return null
    throw new RequestError('VALIDATION_ERROR', 'Localization is not enabled for this workspace', 422)
  }
  if (locale === 'all') return { mode: 'map', locales: 'all' }
  const known = new Set((localization.locales ?? []).map((l) => l?.code))
  const parts = locale.split(',').map((p) => p.trim()).filter(Boolean)
  for (const p of parts) {
    if (p !== localization.defaultLocale && !known.has(p)) {
      throw new RequestError('VALIDATION_ERROR', `Unknown locale "${p}"`, 422)
    }
  }
  if (parts.length > 1) return { mode: 'map', locales: parts }
  if (parts[0] === localization.defaultLocale) return null
  return parts[0] ? { mode: 'overlay', locale: parts[0] } : null
}

/** Filters a full i18n map down to the requested locales ('all' keeps everything). */
export function filterI18nMap(
  map: Record<string, Record<string, unknown>>,
  locales: string[] | 'all',
): Record<string, Record<string, unknown>> {
  if (locales === 'all') return map
  const want = new Set(locales)
  return Object.fromEntries(Object.entries(map).filter(([code]) => want.has(code)))
}

export interface I18nRow {
  objectId: string
  locale: string
  __title?: string | null
  updatedAt?: unknown
  [field: string]: unknown
}

/** Keys on side rows that are plumbing, never content. */
const SIDE_SYSTEM_KEYS = new Set(['objectId', 'locale', 'updatedAt', '__title'])

// ── table resolution (with a test seam) ──────────────────────────────────────
const I18N_TABLE_OVERRIDES = new Map<string, any>()

/** Test hook: register a fixture side table under a type name (undefined clears). */
export function __setI18nTableForTests(typeName: string, table: unknown): void {
  if (table === undefined) I18N_TABLE_OVERRIDES.delete(typeName)
  else I18N_TABLE_OVERRIDES.set(typeName, table)
}

function resolveI18nTable(typeName: string): any | undefined {
  return I18N_TABLE_OVERRIDES.get(typeName) ?? (contentI18nTables as Record<string, any>)[typeName]
}


/**
 * Fetches side-table rows for a set of objects. locale='all' returns every
 * locale's rows (for the editor's i18n map); a concrete locale returns at most
 * one row per object. Types without a side table return [].
 */
export async function fetchI18nRows(
  db: any,
  typeName: string,
  objectIds: string[],
  locale: string,
): Promise<I18nRow[]> {
  const table = resolveI18nTable(typeName)
  if (!table || objectIds.length === 0) return []
  const conds = [inArray(table.objectId, objectIds)]
  if (locale !== 'all') conds.push(eq(table.locale, locale))
  return (await db.select().from(table).where(conds.length === 1 ? conds[0] : and(...conds))) as I18nRow[]
}

/**
 * Overlays a side-table row onto a main-table row: localized fields (and the
 * title via __title) take the translated value when present, otherwise fall
 * back to the default-locale value already in the row. Non-localized fields
 * are untouched; side plumbing keys never leak.
 */
/** Container (component/repeater) field names — their side value is an overlay, not a scalar. */
function containerFieldNames(typeDef: { fields: { name: string; fieldType?: string }[] }): string[] {
  return (typeDef.fields ?? [])
    .filter((f) => f.fieldType === 'component' || f.fieldType === 'repeater')
    .map((f) => f.name)
}

/**
 * BL-2 — merge a per-locale overlay (`{ [_key]: { [sub]: value } }`) into stored
 * blocks/rows. Per-sub-field fallback: only non-empty overlay values replace the
 * base; blocks without an overlay entry pass through; orphan overlay keys are
 * ignored; nested containers (an object overlay value over an array base value)
 * recurse. Fail-open — malformed overlays never damage the base.
 */
export function mergeContainerOverlay(baseRows: unknown, overlay: unknown): unknown {
  if (!Array.isArray(baseRows) || !overlay || typeof overlay !== 'object' || Array.isArray(overlay)) return baseRows
  const byKey = overlay as Record<string, unknown>
  return baseRows.map((row) => {
    const key = (row as Record<string, unknown>)?._key
    const o = typeof key === 'string' ? byKey[key] : undefined
    if (!o || typeof o !== 'object' || Array.isArray(o)) return row
    const out = { ...(row as Record<string, unknown>) }
    for (const [k, v] of Object.entries(o as Record<string, unknown>)) {
      if (v === null || v === undefined || v === '') continue      // fall back to base
      if (k.startsWith('_')) continue                              // meta keys are never localized
      if (Array.isArray(out[k]) && typeof v === 'object' && !Array.isArray(v)) {
        out[k] = mergeContainerOverlay(out[k], v)                  // nested container
      } else {
        out[k] = v
      }
    }
    return out
  })
}

/**
 * The publish-time translation snapshot for one locale, as a synthetic side
 * row consumable by localizeRow. Publish stores buildI18nMap() output under
 * publishedValues.i18n; PUBLIC localized reads must overlay THIS - the live
 * side rows are draft state (translation edits stay in draft until Publish).
 * Returns null when the object has never been published with that locale.
 */
export function publishedI18nSide(raw: Record<string, unknown>, locale: string): I18nRow | null {
  let pv = (raw as Record<string, unknown>).publishedValues ?? (raw as Record<string, unknown>).published_values
  if (typeof pv === 'string') { try { pv = JSON.parse(pv) } catch { return null } }
  const entry = (pv as { i18n?: Record<string, unknown> } | null | undefined)?.i18n?.[locale]
  if (!entry || typeof entry !== 'object') return null
  return { objectId: (raw as Record<string, unknown>).id, locale, ...(entry as Record<string, unknown>) } as I18nRow
}

/**
 * The publish-time translation map (every locale) for map-mode reads - the
 * shape buildI18nMap produces, frozen at publish. PUBLIC `?locale=all` and
 * comma-list reads must attach THIS (K0): the live side rows carry draft
 * translations, and a locale that was never published is absent here.
 */
export function publishedI18nMap(raw: Record<string, unknown>): Record<string, Record<string, unknown>> {
  let pv = (raw as Record<string, unknown>).publishedValues ?? (raw as Record<string, unknown>).published_values
  if (typeof pv === 'string') { try { pv = JSON.parse(pv) } catch { return {} } }
  const map = (pv as { i18n?: unknown } | null | undefined)?.i18n
  if (!map || typeof map !== 'object' || Array.isArray(map)) return {}
  const out: Record<string, Record<string, unknown>> = {}
  for (const [locale, entry] of Object.entries(map as Record<string, unknown>)) {
    if (entry && typeof entry === 'object' && !Array.isArray(entry)) out[locale] = entry as Record<string, unknown>
  }
  return out
}

export function localizeRow(
  row: Record<string, unknown>,
  side: I18nRow | null | undefined,
  typeDef: { fields: { name: string; fieldType?: string; config?: Record<string, unknown> }[] },
): Record<string, unknown> {
  if (!side) return row
  const out = { ...row }
  if (side.__title !== null && side.__title !== undefined && side.__title !== '') {
    out.title = side.__title
  }
  for (const name of localizedFieldNames(typeDef)) {
    const v = side[name]
    // Empty ('' / null / undefined) means "not translated" → keep the default-locale
    // value (same fallback the title uses above), never blank it out.
    if (v !== null && v !== undefined && v !== '') out[name] = v
  }
  // Container overlays — translated sub-values merged into blocks/rows by _key
  for (const name of containerFieldNames(typeDef)) {
    const v = side[name]
    if (v !== null && v !== undefined) out[name] = mergeContainerOverlay(out[name], v)
  }
  return out
}

/**
 * Groups side rows into the editor's map shape:
 * `{ '<locale>': { __title?, '<field>': value } }` — null/absent values dropped.
 */
export function buildI18nMap(
  rows: I18nRow[],
  typeDef: { fields: { name: string; config?: Record<string, unknown> }[] },
): Record<string, Record<string, unknown>> {
  const localized = new Set(localizedFieldNames(typeDef))
  const containers = new Set(containerFieldNames(typeDef as never))
  const map: Record<string, Record<string, unknown>> = {}
  for (const row of rows) {
    const entry: Record<string, unknown> = {}
    if (row.__title !== null && row.__title !== undefined && row.__title !== '') entry.__title = row.__title
    for (const [key, value] of Object.entries(row)) {
      if (SIDE_SYSTEM_KEYS.has(key) || (!localized.has(key) && !containers.has(key))) continue
      if (value !== null && value !== undefined) entry[key] = value
    }
    map[row.locale] = entry
  }
  return map
}

/** Workspace localization config off the loaded project (either shape). */
export function projectLocalization(project: any): LocalizationConfig | undefined {
  return project?.localization ?? project?.config?.localization
}

// ─── Locale-scoped writes ─────────────────────────────────────────────────────

export interface LocalizedUpdate {
  /** Side-table column values — title arrives as __title; null clears. */
  sideValues: Record<string, unknown>
  changedFields: string[]
}

/**
 * Builds the side-row patch for a non-default-locale write. Only `title` and
 * fields marked `localized: true` are accepted — anything else is a 422 (those
 * values are shared across locales and edited in the default locale). Nulls
 * clear a translation, restoring the default-locale fallback.
 */
/**
 * Allowed localized sub-names for a container field. A slot holds SEVERAL
 * components, and two of them may declare the same sub-name with different
 * insides (the Builder Kit's `items` is a button row, a list, an icon list;
 * its `children` is a section's, a container's, a grid's), or one as text and
 * another as a slot. The map is therefore the UNION over the slot's
 * components: a name may be a leaf, a nested map, or both. "Last component
 * wins" would refuse a button label because the list widget also has `items`.
 */
interface AllowedSub { leaf: boolean; subs: AllowedSubs }
interface AllowedSubs { [name: string]: AllowedSub }
function mergeAllowedSubs(into: AllowedSubs, from: AllowedSubs): AllowedSubs {
  for (const [name, sub] of Object.entries(from)) {
    const cur = into[name]
    if (!cur) { into[name] = { leaf: sub.leaf, subs: mergeAllowedSubs({}, sub.subs) }; continue }
    cur.leaf = cur.leaf || sub.leaf
    mergeAllowedSubs(cur.subs, sub.subs)
  }
  return into
}
function allowedLocalizedSubs(
  field: { fieldType?: string; config?: Record<string, unknown> },
  registry: Array<Record<string, unknown>>,
  seen: Set<string> = new Set(),
): AllowedSubs {
  const out: AllowedSubs = {}
  const collect = (subs: Array<Record<string, unknown>> | undefined) => {
    for (const sf of subs ?? []) {
      const cfg = (sf.config ?? {}) as Record<string, unknown>
      const name = sf.name as string
      if (sf.fieldType === 'component' || sf.fieldType === 'repeater') {
        const nested = allowedLocalizedSubs(sf as never, registry, seen)
        if (Object.keys(nested).length > 0) mergeAllowedSubs(out, { [name]: { leaf: false, subs: nested } })
      } else if (cfg.localized === true && isLocalizableFieldType(sf.fieldType as string)) {
        mergeAllowedSubs(out, { [name]: { leaf: true, subs: {} } })
      }
    }
  }
  if (field.fieldType === 'repeater') collect((field.config as any)?.fields)
  else if (field.fieldType === 'component') {
    for (const ref of ((field.config as any)?.components ?? []) as Array<string | Record<string, unknown>>) {
      const def = typeof ref === 'string' ? registry.find((c) => c.name === ref) : ref
      if (!def) continue
      if (typeof ref === 'string') {
        if (seen.has(def.name as string)) continue
        seen.add(def.name as string)
      }
      collect((def as any).fields)
    }
  }
  return out
}

/** 422 unless `overlay` is `{ [_key]: { <localized sub>: value } }` for this container. */
function assertOverlayShape(fieldName: string, overlay: unknown, allowed: AllowedSubs): void {
  if (!overlay || typeof overlay !== 'object' || Array.isArray(overlay)) {
    throw new RequestError('VALIDATION_ERROR',
      `"${fieldName}" translations must be an object keyed by block/row _key`, 422)
  }
  for (const [key, entry] of Object.entries(overlay as Record<string, unknown>)) {
    if (!entry || typeof entry !== 'object' || Array.isArray(entry)) {
      throw new RequestError('VALIDATION_ERROR',
        `"${fieldName}.${key}" must be an object of localized sub-field values`, 422)
    }
    for (const [sub, v] of Object.entries(entry as Record<string, unknown>)) {
      const kind = allowed[sub]
      if (!kind) {
        throw new RequestError('VALIDATION_ERROR',
          `"${fieldName}.${key}.${sub}" is not localized - shared values are edited in the default locale`, 422)
      }
      const hasSubs = Object.keys(kind.subs).length > 0
      // A nested map (not a richtext document, which is a leaf value) is
      // checked against the nested slot; anything else must be a leaf here.
      const isMap = !!v && typeof v === 'object' && !Array.isArray(v)
      const isRichDoc = isMap && typeof (v as { type?: unknown }).type === 'string'
      if (hasSubs && isMap && !(kind.leaf && isRichDoc)) {
        assertOverlayShape(`${fieldName}.${key}.${sub}`, v, kind.subs)
      } else if (!kind.leaf) {
        assertOverlayShape(`${fieldName}.${key}.${sub}`, v, kind.subs)
      }
    }
  }
}

export function buildLocalizedUpdate(
  typeDef: { fields: { name: string; fieldType?: string; config?: Record<string, unknown> }[] },
  body: Record<string, unknown>,
  registry: Array<Record<string, unknown>> = [],
): LocalizedUpdate {
  const localized = new Set(localizedFieldNames(typeDef))
  const containers = new Set(localizedContainerFields(typeDef.fields as never, registry as never))
  const fieldByName = new Map(typeDef.fields.map((f) => [f.name, f]))
  const sideValues: Record<string, unknown> = {}
  const changedFields: string[] = []

  for (const [key, value] of Object.entries(body ?? {})) {
    if (value === undefined) continue
    if (key === 'title') {
      sideValues.__title = value === null ? null : String(value).trim()
      changedFields.push('title')
    } else if (containers.has(key)) {
      // BL-3: container translations arrive as an overlay, not full blocks
      if (value !== null) {
        assertOverlayShape(key, value, allowedLocalizedSubs(fieldByName.get(key)! as never, registry))
      }
      sideValues[key] = value
      changedFields.push(key)
    } else if (localized.has(key)) {
      sideValues[key] = value
      changedFields.push(key)
    } else {
      throw new RequestError(
        'VALIDATION_ERROR',
        `Field "${key}" is not localized - shared values are edited in the default locale`,
        422,
      )
    }
  }

  if (changedFields.length === 0) {
    throw new RequestError('VALIDATION_ERROR', 'No localized fields provided', 422)
  }
  return { sideValues, changedFields }
}

/**
 * Upserts a locale's side row for one object. Missing side table (push not
 * run) surfaces as a clear error rather than a silent no-op.
 */
export async function upsertI18nRow(
  db: any,
  typeName: string,
  objectId: string,
  locale: string,
  sideValues: Record<string, unknown>,
): Promise<void> {
  const table = resolveI18nTable(typeName)
  if (!table) {
    throw new RequestError('VALIDATION_ERROR', `Type "${typeName}" has no localized fields - run tangen push after marking fields localized`, 422)
  }
  await db
    .insert(table)
    .values({ objectId, locale, ...sideValues, updatedAt: new Date() })
    .onConflictDoUpdate({
      target: [table.objectId, table.locale],
      set: { ...sideValues, updatedAt: new Date() },
    })
}

/**
 * BL-3 — overlay GC: entries whose block/row `_key` no longer exists in the base
 * structure are dropped. Returns null when nothing (valid) remains or the stored
 * value is malformed.
 */
export function stripOrphanOverlayKeys(stored: unknown, validKeys: Set<string>): Record<string, unknown> | null {
  if (!stored || typeof stored !== 'object' || Array.isArray(stored)) return null
  const out: Record<string, unknown> = {}
  for (const [k, v] of Object.entries(stored as Record<string, unknown>)) {
    if (validKeys.has(k)) out[k] = v
  }
  return Object.keys(out).length > 0 ? out : null
}

/**
 * After a BASE write changes a container field's structure, drop orphaned
 * overlay entries from every locale row. Best-effort: absent side table or
 * column is a no-op.
 */
export async function pruneContainerOverlays(
  db: any,
  typeName: string,
  objectId: string,
  containerValues: Record<string, unknown>,
): Promise<void> {
  const table = resolveI18nTable(typeName)
  if (!table) return
  const containerNames = Object.keys(containerValues).filter((n) => table[n] !== undefined)
  if (containerNames.length === 0) return

  const rows = await db.select().from(table).where(eq(table.objectId, objectId))
  for (const row of rows as Array<Record<string, unknown>>) {
    const patch: Record<string, unknown> = {}
    for (const name of containerNames) {
      const stored = row[name]
      if (stored === null || stored === undefined) continue
      const validKeys = new Set(
        (Array.isArray(containerValues[name]) ? containerValues[name] as Array<Record<string, unknown>> : [])
          .map((b) => b?._key)
          .filter((k): k is string => typeof k === 'string'),
      )
      const stripped = stripOrphanOverlayKeys(stored, validKeys)
      if (JSON.stringify(stripped) !== JSON.stringify(stored)) patch[name] = stripped
    }
    if (Object.keys(patch).length > 0) {
      const conds = [eq(table.objectId, objectId), eq(table.locale, row.locale)]
      await db.update(table).set(patch).where(and(...conds))
    }
  }
}

/** Deletes every locale's side row for the given objects (object deletion). */
export async function deleteI18nRows(db: any, typeName: string, objectIds: string[]): Promise<void> {
  const table = resolveI18nTable(typeName)
  if (!table || objectIds.length === 0) return
  await db.delete(table).where(inArray(table.objectId, objectIds))
}

// ─── Globals localization ─────────────────────────────────────────────────────
// Globals are schemaless jsonb — translations live under data.__i18n[locale]
// and overlay the top-level keys at read time.

/** Overlays data.__i18n[locale] over the top-level keys; __i18n never leaks. */
export function localizeGlobalData(
  data: Record<string, unknown>,
  locale: string | null | undefined,
): Record<string, unknown> {
  const { __i18n, ...rest } = (data ?? {}) as Record<string, unknown> & { __i18n?: Record<string, Record<string, unknown>> }
  if (!locale || !__i18n || typeof __i18n !== 'object') return rest
  const section = __i18n[locale]
  if (!section || typeof section !== 'object') return rest
  const out = { ...rest }
  for (const [k, v] of Object.entries(section)) {
    if (v !== null && v !== undefined) out[k] = v
  }
  return out
}

/** Merges a locale's patch under data.__i18n[locale]; defaults untouched. */
export function mergeGlobalLocaleData(
  existing: Record<string, unknown>,
  locale: string,
  patch: Record<string, unknown>,
): Record<string, unknown> {
  const current = (existing ?? {}) as Record<string, unknown> & { __i18n?: Record<string, Record<string, unknown>> }
  const i18n = { ...(current.__i18n ?? {}) }
  i18n[locale] = { ...(i18n[locale] ?? {}), ...patch }
  return { ...current, __i18n: i18n }
}
